import {copy,validateProject} from './music.js';
import {PROJECT_STARTS,createStartProject} from './project-starts.js';
import {LIBRARY_LIMITS} from './project-library.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const size=n=>n<1048576?Math.round(n/1024)+' KiB':(n/1048576).toFixed(2)+' MiB';
export function createLibraryUI({library,getCurrent,transition,modal,toast,download,projectFilename}){
 let request=0,archived=false;
 const fail=error=>{const target=$('#library-error');if(target)target.textContent=error.message;else toast(error.message)};
 async function show(){
  const at=++request;modal('我的工程','<div class="project-library"><p>正在读取本机工程库…</p></div>');
  try{await library.reload();const rows=await library.list();if(at!==request||!$('#modal').open||$('#modal-content h2')?.textContent!=='我的工程')return;const current=getCurrent(),view=rows.filter(r=>r.archived===archived),total=rows.reduce((n,r)=>n+r.bytes,0);
   modal('我的工程',`<div class="project-library"><p>每首作品分开保存音乐、撤销 / 重做与版本。打开前会先保存当前工程；不会播放声音。</p><div class="library-tools"><button id="library-new" class="accent">新建工程</button><button id="library-import" class="quiet">导入为新工程</button><button id="library-toggle" class="quiet">${archived?'回到作品':'查看归档'} (${rows.filter(r=>r.archived!==archived).length})</button><button id="library-reload" class="quiet">重新读取</button></div><input type="file" id="library-file" accept=".sprout,.json,application/json" hidden><div id="library-error" class="export-progress" role="status"></div><div class="library-projects">${view.length?view.map(row=>`<article class="library-project ${row.id===current.id?'current':''}" data-library-id="${escape(row.id)}"><div><strong>${escape(row.summary?.name||'无法校验的工程')}</strong><small>${row.id===current.id?'正在编辑 · ':''}${row.archived?'已归档 · ':''}${row.recovered?'最近记录损坏，使用有效旧版 · ':''}${row.valid?`${row.summary.bars} 小节 · ${row.summary.tracks} 轨 · ${row.summary.notes} 音符`:'原记录保留；可下载排查'}</small></div>${row.valid?`<div class="library-metrics"><span>${row.summary.bpm} BPM · ${escape(row.summary.key)}</span><span>${row.versions} 版本 · ${size(row.bytes)}</span></div>`:''}<div class="library-row-actions"><button class="${row.id===current.id?'quiet':'accent'}" data-library-open="${escape(row.id)}" ${row.id===current.id||!row.valid||row.archived?'disabled':''}>${row.id===current.id?'当前工程':'打开工程'}</button>${row.archived?`<button class="quiet" data-library-restore="${escape(row.id)}">恢复归档</button>`:`<button class="quiet" data-library-copy="${escape(row.id)}" ${row.valid?'':'disabled'}>另存副本</button><button class="quiet" data-library-archive="${escape(row.id)}" ${row.id===current.id?'disabled':''}>归档</button>`}<button class="quiet" data-library-download="${escape(row.id)}">${row.valid?'下载工程':'下载原记录'}</button></div></article>`).join(''):`<p class="empty-versions">${archived?'归档里还没有作品。':'还没有可显示的工程。'}</p>`}</div><div class="modal-notice">仅此浏览器 / 此网站，不是云备份。${rows.length} / ${LIBRARY_LIMITS.projects} 个工程（含归档），版本记录约 ${size(total)}，不含应急记录与共享候选架。归档不删除内容、不释放配额；没有自动淘汰作品。候选架与编曲参数仍跨工程共用，应用候选前会检查原稿指纹。重要作品请下载文件。</div></div>`);
   $('#library-new').onclick=()=>newForm();$('#library-reload').onclick=show;$('#library-toggle').onclick=()=>{archived=!archived;show()};
   $('#library-import').onclick=()=>$('#library-file').click();$('#library-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>3e6)throw Error('工程文件不能超过 3 MB');const p=validateProject(JSON.parse(await f.text()));if(at!==request||!$('#modal').open||$('#modal-content h2')?.textContent!=='我的工程')return;newForm(p)}catch(error){if(at===request&&$('#modal').open&&$('#modal-content h2')?.textContent==='我的工程')fail(error)}finally{e.target.value=''}};
   document.querySelectorAll('[data-library-open]').forEach(b=>b.onclick=async()=>{try{await transition({expected:current,action:()=>library.openProject(b.dataset.libraryOpen)})}catch(error){fail(error)}});
   document.querySelectorAll('[data-library-copy]').forEach(b=>b.onclick=async()=>{try{const p=b.dataset.libraryCopy===current.id?copy(current.project):await library.getProject(b.dataset.libraryCopy);await transition({expected:current,action:async()=>{const created=await library.create(p,{duplicate:true});return library.openProject(created.id)}})}catch(error){fail(error)}});
   document.querySelectorAll('[data-library-download]').forEach(b=>b.onclick=async()=>{try{const row=rows.find(r=>r.id===b.dataset.libraryDownload);if(row.valid){const p=row.id===current.id?copy(getCurrent().project):await library.getProject(row.id);download(JSON.stringify(p,null,2),projectFilename(p)+'.sprout','application/json')}else download(await library.getRaw(row.id),'sprout-workspace-record.json','application/json');toast('工程库记录已下载，不会播放。')}catch(error){fail(error)}});
   document.querySelectorAll('[data-library-archive]').forEach(b=>b.onclick=()=>{const row=rows.find(r=>r.id===b.dataset.libraryArchive);modal('归档这个工程？',`<div class="project-library"><p>“${escape(row.summary?.name||'这个工程')}”将移到归档列表，音乐、历史和版本都保留。可以恢复；不会永久删除，也不释放存储。</p><div id="library-error" role="status" class="export-progress"></div></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="library-confirm-archive">移到归档，不删除</button>');$('#library-confirm-archive').onclick=async()=>{try{await library.archive(row.id);await show();toast('已归档，可以在归档列表恢复。')}catch(error){fail(error)}}});
   document.querySelectorAll('[data-library-restore]').forEach(b=>b.onclick=async()=>{try{await library.restore(b.dataset.libraryRestore);await show();toast('工程已恢复到作品列表。')}catch(error){fail(error)}});
  }catch(error){if(at!==request||!$('#modal').open||$('#modal-content h2')?.textContent!=='我的工程')return;modal('我的工程',`<div class="project-library"><p>${escape(error.message)}</p><p>没有删除或重置本机记录。当前编辑仍可下载；存储恢复前不切换工程。</p><div id="library-error" role="status" class="export-progress"></div><button class="quiet" id="library-reload">重新读取</button><button class="accent" id="library-export-current">下载当前工程</button></div>`);$('#library-reload').onclick=show;$('#library-export-current').onclick=()=>{const p=getCurrent().project;download(JSON.stringify(p,null,2),projectFilename(p)+'.sprout','application/json')}}
 }
 function newForm(imported){
  ++request;const current=getCurrent();modal(imported?'导入为独立工程':'新建一个工程',`<div class="project-library library-new-form"><p>${imported?`已读到 ${imported.bars} 小节 / ${imported.tracks.length} 轨 / ${imported.tracks.reduce((n,t)=>n+t.notes.length,0)} 音符。保留音乐与设置，分配独立工程标识，不替换旧作品。`:'先取个名字。空白工程适合自己画音符；规则起点不调用大模型。'}</p><label class="modal-label">工程名称<input id="library-name" aria-label="新工程名称" maxlength="60" value="${escape(imported?.name||'我的第一首歌')}"></label>${imported?'':`<label class="modal-label">创作起点<select id="library-template" aria-label="新工程起点">${PROJECT_STARTS.map(s=>`<option value="${s.id}">${escape(s.label)}</option>`).join('')}</select></label><label class="modal-label">长度<select id="library-bars" aria-label="新工程长度"><option value="8">8 小节</option><option value="16">16 小节</option><option value="32">32 小节</option></select></label>`}<div id="library-error" class="export-progress" role="status"></div><div class="modal-notice">当前工程先保存。新工程的撤销 / 重做与保存点从零开始，旧作品保持原样；不会播放声音。${imported?'这不是 .flp 导入。':'规则起点使用本机模板，不是真实 LLM。'}</div></div>`,'<button class="quiet" data-close>取消</button><button id="library-create" class="accent">保存并打开新工程</button>');
  $('#library-create').onclick=async()=>{try{const name=$('#library-name').value.trim();if(!name)throw Error('请给工程起一个名字');let p=imported?copy(imported):createStartProject({template:$('#library-template').value,bars:+$('#library-bars').value});await transition({expected:current,action:async()=>{const created=await library.create(p,{name});return library.openProject(created.id)}})}catch(error){fail(error)}};
 }
 return{show,newForm};
}
